+		Page:       page,
+		TotalPages: totalPages,
+		Limit:      limit,
+		Counts:     resp.Counts,
+	}
+	data, err := jsonutil.MarshalIndentWithNewline(out, "", "  ")
+	if err != nil {
+		return fmt.Errorf("marshaling compact results: %w", err)
+	}
+	fmt.Fprint(w, string(data))
+	return nil
+}

